{{ config(materialized='table') }}

    with
    ap_supplier_sites_all as (
    select * from {{ ref("ap_supplier_sites_all") }}
),
ap_terms_tl as (
    select * from {{ ref("ap_terms_tl") }}
),
ap_suppliers as (
    select * from {{ ref("ap_suppliers") }}
),
hz_parties as (
    select * from {{ ref("hz_parties") }}
),
hz_party_sites as (
    select * from {{ ref("hz_party_sites") }}
),
hz_locations as (
    select * from {{ ref("hz_locations") }}
),
hr_operating_units as (
    select * from {{ ref("hr_operating_units") }}
),
ct_supplier_d_stg as (
    SELECT AP_SUPPLIER_SITES_ALL.VENDOR_ID AS SUPPLIER_ID, AP_SUPPLIER_SITES_ALL.VENDOR_SITE_ID AS SUPPLIER_SITE_NUM, AP_SUPPLIERS.SEGMENT1 AS SUPPLIER_NUM, AP_SUPPLIERS.VENDOR_NAME AS SUPPLIER_NAME, AP_SUPPLIER_SITES_ALL.VENDOR_SITE_CODE AS SUPPLIER_SITE_CODE, HZ_PARTIES.PARTY_ID AS SUP_PARTY_ID, HZ_PARTIES.PARTY_NUMBER AS PARTY_NUM, HZ_PARTIES.PARTY_NAME AS PARTY_NAME, COALESCE(HZ_LOCATIONS.ADDRESS1, AP_SUPPLIER_SITES_ALL.ADDRESS_LINE1) AS ADDRESS1, COALESCE(HZ_LOCATIONS.ADDRESS2, AP_SUPPLIER_SITES_ALL.ADDRESS_LINE2) AS ADDRESS2, COALESCE(HZ_LOCATIONS.ADDRESS3, AP_SUPPLIER_SITES_ALL.ADDRESS_LINE3) AS ADDRESS3, COALESCE(HZ_LOCATIONS.ADDRESS4, AP_SUPPLIER_SITES_ALL.ADDRESS_LINE4) AS ADDRESS4, COALESCE(HZ_LOCATIONS.POSTAL_CODE, AP_SUPPLIER_SITES_ALL.ZIP) AS POSTAL_CODE, COALESCE(HZ_LOCATIONS.CITY, AP_SUPPLIER_SITES_ALL.CITY) AS CITY, COALESCE(HZ_LOCATIONS.STATE, AP_SUPPLIER_SITES_ALL.STATE) AS STATE, COALESCE(HZ_LOCATIONS.COUNTRY, AP_SUPPLIER_SITES_ALL.COUNTRY) AS COUNTRY, AP_SUPPLIER_SITES_ALL.EMAIL_ADDRESS AS EMAIL_ADDRESS, TO_CHAR(AP_SUPPLIER_SITES_ALL.INACTIVE_DATE, 'DD-MON-YY') AS SITE_INACTIVE_DT, HZ_PARTY_SITES.PARTY_SITE_NUMBER AS PARTY_SITE_NUM, HZ_PARTY_SITES.PARTY_SITE_NAME AS PARTY_SITE_NAME, AP_SUPPLIER_SITES_ALL.PAY_GROUP_LOOKUP_CODE AS PAY_GROUP_LOOKUP_CODE, AP_SUPPLIERS.VENDOR_TYPE_LOOKUP_CODE AS VENDOR_TYPE_LOOKUP_CODE, AP_SUPPLIERS.SET_OF_BOOKS_ID AS SET_OF_BOOKS_ID, AP_SUPPLIERS.ONE_TIME_FLAG AS ONE_TIME_FLAG, NULL AS REVIEW_TYPE, AP_SUPPLIERS.STANDARD_INDUSTRY_CLASS AS STANDARD_INDUSTRY_CLASS, AP_SUPPLIERS.ORGANIZATION_TYPE_LOOKUP_CODE AS ORGANIZATION_TYPE_LOOKUP_CODE, AP_SUPPLIERS.ENABLED_FLAG AS ENABLED_FLAG, NULL AS STATE_REPORTABLE_FLAG, NULL AS FEDERAL_REPORTABLE_FLAG, AP_SUPPLIER_SITES_ALL.INVOICE_CURRENCY_CODE AS INVOICE_CURRENCY_CODE, AP_SUPPLIER_SITES_ALL.PAYMENT_CURRENCY_CODE AS PAYMENT_CURRENCY_CODE, AP_SUPPLIER_SITES_ALL.VAT_REGISTRATION_NUM AS VAT_NUM, AP_TERMS_TL.NAME AS PAYMENT_TERMS, AP_SUPPLIER_SITES_ALL.CREATION_DATE AS CREATION_DT, AP_SUPPLIER_SITES_ALL.LAST_UPDATE_DATE AS LAST_UPDATE_DT, AP_SUPPLIER_SITES_ALL.CREATED_BY AS CREATED_BY, AP_SUPPLIER_SITES_ALL.LAST_UPDATED_BY AS LAST_UPDATED_BY, COALESCE(CAST(AP_SUPPLIER_SITES_ALL.VENDOR_ID AS VARCHAR), '0') || '~' || COALESCE(CAST(AP_SUPPLIER_SITES_ALL.VENDOR_SITE_ID AS VARCHAR), '0') AS INTEGRATION_ID, 1000 AS DATASOURCE_NUM_ID, CASE WHEN AP_SUPPLIERS.ENABLED_FLAG = 'Y' THEN 'Active' ELSE 'Inactive' END AS ACTIVE_FLAG, 'N' AS DELETE_FLAG, GETDATE() AS W_INSERT_DT, GETDATE() AS W_UPDATE_DT, HR_OPERATING_UNITS.NAME AS OPERATING_UNIT, AP_SUPPLIER_SITES_ALL.PAYMENT_METHOD_LOOKUP_CODE AS PAYMENT_METHOD_LOOKUP_CODE, AP_SUPPLIER_SITES_ALL.TERMS_DATE_BASIS AS TERMS_DATE_BASIS, AP_SUPPLIER_SITES_ALL.PURCHASING_SITE_FLAG AS PURCHASING_SITE_FLAG, AP_SUPPLIER_SITES_ALL.RFQ_ONLY_SITE_FLAG AS RFQ_ONLY_SITE_FLAG, AP_SUPPLIER_SITES_ALL.PAY_SITE_FLAG AS PAY_SITE_FLAG FROM ap_supplier_sites_all AP_SUPPLIER_SITES_ALL LEFT JOIN ap_terms_tl AP_TERMS_TL ON AP_TERMS_TL.TERM_ID = AP_SUPPLIER_SITES_ALL.TERMS_ID AND AP_TERMS_TL.LANGUAGE = 'US' INNER JOIN ap_suppliers AP_SUPPLIERS ON AP_SUPPLIER_SITES_ALL.VENDOR_ID = AP_SUPPLIERS.VENDOR_ID INNER JOIN hz_parties HZ_PARTIES ON AP_SUPPLIERS.PARTY_ID = HZ_PARTIES.PARTY_ID LEFT JOIN hz_party_sites HZ_PARTY_SITES ON AP_SUPPLIER_SITES_ALL.PARTY_SITE_ID = HZ_PARTY_SITES.PARTY_SITE_ID LEFT JOIN hz_locations HZ_LOCATIONS ON AP_SUPPLIER_SITES_ALL.LOCATION_ID = HZ_LOCATIONS.LOCATION_ID LEFT JOIN hr_operating_units HR_OPERATING_UNITS ON AP_SUPPLIER_SITES_ALL.ORG_ID = HR_OPERATING_UNITS.ORGANIZATION_ID UNION SELECT SUP.VENDOR_ID AS SUPPLIER_ID, NULL AS SUPPLIER_SITE_NUM, SUP.SEGMENT1 AS SUPPLIER_NUM, SUP.VENDOR_NAME AS SUPPLIER_NAME, NULL AS SUPPLIER_SITE_CODE, PARTY.PARTY_ID AS SUP_PARTY_ID, PARTY.PARTY_NUMBER AS PARTY_NUM, PARTY.PARTY_NAME AS PARTY_NAME, LOCATION.ADDRESS1 AS ADDRESS1, LOCATION.ADDRESS2 AS ADDRESS2, LOCATION.ADDRESS3 AS ADDRESS3, LOCATION.ADDRESS4 AS ADDRESS4, LOCATION.POSTAL_CODE AS POSTAL_CODE, LOCATION.CITY AS CITY, LOCATION.STATE AS STATE, LOCATION.COUNTRY AS COUNTRY, NULL AS EMAIL_ADDRESS, NULL AS SITE_INACTIVE_DT, NULL AS PARTY_SITE_NUM, NULL AS PARTY_SITE_NAME, SUP.PAY_GROUP_LOOKUP_CODE AS PAY_GROUP_LOOKUP_CODE, SUP.VENDOR_TYPE_LOOKUP_CODE AS VENDOR_TYPE_LOOKUP_CODE, SUP.SET_OF_BOOKS_ID AS SET_OF_BOOKS_ID, SUP.ONE_TIME_FLAG AS ONE_TIME_FLAG, NULL AS REVIEW_TYPE, SUP.STANDARD_INDUSTRY_CLASS AS STANDARD_INDUSTRY_CLASS, SUP.ORGANIZATION_TYPE_LOOKUP_CODE AS ORGANIZATION_TYPE_LOOKUP_CODE, SUP.ENABLED_FLAG AS ENABLED_FLAG, NULL AS STATE_REPORTABLE_FLAG, NULL AS FEDERAL_REPORTABLE_FLAG, SUP.INVOICE_CURRENCY_CODE AS INVOICE_CURRENCY_CODE, SUP.PAYMENT_CURRENCY_CODE AS PAYMENT_CURRENCY_CODE, SUP.VAT_REGISTRATION_NUM AS VAT_NUM, APT.NAME AS PAYMENT_TERMS, SUP.CREATION_DATE AS CREATION_DT, SUP.LAST_UPDATE_DATE AS LAST_UPDATE_DT, SUP.CREATED_BY AS CREATED_BY, SUP.LAST_UPDATED_BY AS LAST_UPDATED_BY, COALESCE(CAST(SUP.VENDOR_ID AS VARCHAR), '0') || '~0' AS INTEGRATION_ID, 1000 AS DATASOURCE_NUM_ID, CASE WHEN SUP.ENABLED_FLAG = 'Y' THEN 'Active' ELSE 'Inactive' END AS ACTIVE_FLAG, 'N' AS DELETE_FLAG, GETDATE() AS W_INSERT_DT, GETDATE() AS W_UPDATE_DT, NULL AS OPERATING_UNIT, NULL AS PAYMENT_METHOD_LOOKUP_CODE, NULL AS TERMS_DATE_BASIS, NULL AS PURCHASING_SITE_FLAG, NULL AS RFQ_ONLY_SITE_FLAG, NULL AS PAY_SITE_FLAG FROM ap_suppliers SUP LEFT JOIN ap_terms_tl APT ON APT.TERM_ID = SUP.TERMS_ID AND APT.LANGUAGE = 'US' INNER JOIN hz_parties PARTY ON SUP.PARTY_ID = PARTY.PARTY_ID LEFT JOIN hz_locations LOCATION ON SUP.BILL_TO_LOCATION_ID = LOCATION.LOCATION_ID
)
    select * from ct_supplier_d_stg;
